import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { GoogleGenAI } from '@google/genai';

let aiClient: GoogleGenAI | null = null;
function getAIClient(): GoogleGenAI | null {
  if (!aiClient && process.env.GEMINI_API_KEY) {
    aiClient = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
  }
  return aiClient;
}

interface UserStore {
  email: string;
  username: string;
  passwordHash: string;
  token: string;
  cloudSyncData?: {
    payload: any;
    updatedAt: string;
    isEncrypted: boolean;
  };
}

const usersMemoryDB = new Map<string, UserStore>();

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json({ limit: '10mb' }));

  // API Routes
  app.get('/api/health', (_req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Auth: Register
  app.post('/api/auth/register', (req, res) => {
    const { email, username, password } = req.body;
    if (!email || !username || !password) {
      res.status(400).json({ error: 'Todos los campos son requeridos' });
      return;
    }

    const lowerEmail = email.toLowerCase().trim();
    if (usersMemoryDB.has(lowerEmail)) {
      res.status(400).json({ error: 'El usuario ya existe con este correo electrónico' });
      return;
    }

    const token = `token_${Date.now()}_${Math.random().toString(36).substring(2)}`;
    const newUser: UserStore = {
      email: lowerEmail,
      username,
      passwordHash: Buffer.from(password).toString('base64'),
      token,
    };

    usersMemoryDB.set(lowerEmail, newUser);
    res.json({
      message: 'Cuenta creada con éxito',
      user: { email: newUser.email, username: newUser.username, token: newUser.token },
    });
  });

  // Auth: Login
  app.post('/api/auth/login', (req, res) => {
    const { email, password } = req.body;
    if (!email || !password) {
      res.status(400).json({ error: 'Correo y contraseña requeridos' });
      return;
    }

    const lowerEmail = email.toLowerCase().trim();
    const user = usersMemoryDB.get(lowerEmail);

    if (!user || user.passwordHash !== Buffer.from(password).toString('base64')) {
      res.status(401).json({ error: 'Credenciales inválidas' });
      return;
    }

    res.json({
      message: 'Inicio de sesión correcto',
      user: { email: user.email, username: user.username, token: user.token },
      hasBackup: !!user.cloudSyncData,
      lastSyncTime: user.cloudSyncData?.updatedAt,
    });
  });

  // Cloud Sync: Upload Backup
  app.post('/api/sync/upload', (req, res) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({ error: 'No autorizado' });
      return;
    }

    const token = authHeader.split(' ')[1];
    let foundUser: UserStore | undefined;
    for (const u of usersMemoryDB.values()) {
      if (u.token === token) {
        foundUser = u;
        break;
      }
    }

    if (!foundUser) {
      res.status(401).json({ error: 'Sesión no válida' });
      return;
    }

    const { payload, isEncrypted } = req.body;
    if (!payload) {
      res.status(400).json({ error: 'Payload de sincronización no proporcionado' });
      return;
    }

    foundUser.cloudSyncData = {
      payload,
      updatedAt: new Date().toISOString(),
      isEncrypted: !!isEncrypted,
    };

    res.json({
      message: 'Sincronización en la nube completada con éxito',
      updatedAt: foundUser.cloudSyncData.updatedAt,
      isEncrypted: foundUser.cloudSyncData.isEncrypted,
    });
  });

  // Cloud Sync: Download Backup
  app.get('/api/sync/download', (req, res) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({ error: 'No autorizado' });
      return;
    }

    const token = authHeader.split(' ')[1];
    let foundUser: UserStore | undefined;
    for (const u of usersMemoryDB.values()) {
      if (u.token === token) {
        foundUser = u;
        break;
      }
    }

    if (!foundUser || !foundUser.cloudSyncData) {
      res.status(444).json({ error: 'No se encontraron datos de copia de seguridad en la nube' });
      return;
    }

    res.json({
      payload: foundUser.cloudSyncData.payload,
      updatedAt: foundUser.cloudSyncData.updatedAt,
      isEncrypted: foundUser.cloudSyncData.isEncrypted,
    });
  });

  // AI Tag Suggestions via Gemini
  app.post('/api/suggest-tags', async (req, res) => {
    const { title = '', description = '' } = req.body;
    if (!title && !description) {
      res.json({ tags: [] });
      return;
    }

    const ai = getAIClient();
    if (ai) {
      try {
        const response = await ai.models.generateContent({
          model: 'gemini-3.6-flash',
          contents: `Analiza el siguiente título y descripción de un enlace o marcador y devuelve únicamente un JSON array de strings con entre 3 y 6 etiquetas (tags) cortas y relevantes en español.
Título: "${title}"
Descripción: "${description}"
Responde solo con el JSON array, ejemplo: ["tecnologia", "desarrollo", "tutorial"]`,
        });
        const text = response.text || '';
        const jsonMatch = text.match(/\[[\s\S]*\]/);
        if (jsonMatch) {
          const parsed = JSON.parse(jsonMatch[0]);
          if (Array.isArray(parsed) && parsed.length > 0) {
            res.json({ tags: parsed.slice(0, 6).map((t: string) => String(t).trim().toLowerCase()) });
            return;
          }
        }
      } catch (e) {
        console.warn('Error calling Gemini for tag suggestions:', e);
      }
    }

    // Fallback keyword extraction if Gemini unavailable
    const combined = `${title} ${description}`.toLowerCase();
    const stopWords = ['para', 'como', 'con', 'este', 'esta', 'sobre', 'desde', 'https', 'http', 'www', 'com', 'para', 'cada', 'pero'];
    const words = Array.from(new Set(combined.replace(/[^\wáéíóúñ\s]/gi, '').split(/\s+/)))
      .filter((w) => w.length > 3 && !stopWords.includes(w));

    res.json({ tags: words.slice(0, 5) });
  });

  // Auto Categorize Cards via Gemini API
  app.post('/api/auto-categorize', async (req, res) => {
    const { cards = [] } = req.body;
    if (!Array.isArray(cards) || cards.length === 0) {
      res.json({ categorizedCards: [] });
      return;
    }

    const ai = getAIClient();
    if (ai) {
      try {
        const response = await ai.models.generateContent({
          model: 'gemini-3.6-flash',
          contents: `Analiza los siguientes marcadores/enlaces web (con su id, título, url y descripción) y sugiere para cada uno una categoría corta, clara e inteligible en español (por ejemplo: "Desarrollo", "Diseño UI", "Herramientas", "Recursos", "Noticias", "Productividad", "Educación", "Entretenimiento", "Redes Sociales", "Finanzas").

Enlaces a categorizar:
${JSON.stringify(cards.map((c: any) => ({ id: c.id, title: c.title, url: c.href || c.url, description: c.description || c.texto || '' })))}

Responde ÚNICAMENTE en formato JSON con la siguiente estructura exacta:
{
  "categorizedCards": [
    { "id": 1, "category": "Desarrollo" }
  ]
}`,
          config: {
            responseMimeType: 'application/json',
          },
        });

        const text = response.text || '';
        const jsonMatch = text.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
          const parsed = JSON.parse(jsonMatch[0]);
          if (parsed && Array.isArray(parsed.categorizedCards)) {
            res.json({ categorizedCards: parsed.categorizedCards });
            return;
          }
        }
      } catch (e) {
        console.warn('Error calling Gemini for auto-categorize:', e);
      }
    }

    // Fallback heuristic if Gemini API is unavailable
    const fallbackResults = cards.map((c: any) => {
      const text = `${c.title || ''} ${c.href || c.url || ''} ${c.description || c.texto || ''}`.toLowerCase();
      let category = 'General';
      if (text.includes('github') || text.includes('code') || text.includes('dev') || text.includes('script') || text.includes('api') || text.includes('npm') || text.includes('ts') || text.includes('react')) {
        category = 'Desarrollo';
      } else if (text.includes('design') || text.includes('ui') || text.includes('ux') || text.includes('css') || text.includes('dribbble') || text.includes('figma') || text.includes('color') || text.includes('icon')) {
        category = 'Diseño UI';
      } else if (text.includes('tool') || text.includes('app') || text.includes('generator') || text.includes('converter') || text.includes('util')) {
        category = 'Herramientas';
      } else if (text.includes('photo') || text.includes('image') || text.includes('unsplash') || text.includes('stock') || text.includes('resource') || text.includes('vector')) {
        category = 'Recursos';
      } else if (text.includes('doc') || text.includes('guide') || text.includes('tutorial') || text.includes('wiki') || text.includes('mdn')) {
        category = 'Documentación';
      }
      return { id: c.id, category };
    });

    res.json({ categorizedCards: fallbackResults });
  });

  // Fetch Favicon or Apple-Touch-Icon for a URL
  app.post('/api/fetch-site-icon', async (req, res) => {
    const { url } = req.body;
    if (!url) {
      res.status(400).json({ error: 'URL requerida' });
      return;
    }

    let formattedUrl = String(url).trim();
    if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
      formattedUrl = `https://${formattedUrl}`;
    }

    try {
      const urlObj = new URL(formattedUrl);
      const origin = urlObj.origin;
      const hostname = urlObj.hostname;

      let candidateIcon: string | null = null;
      let source: 'apple-touch-icon' | 'favicon' | 'html-link' | 'google-s2' = 'google-s2';

      // 1. Attempt to fetch HTML and extract <link rel="apple-touch-icon"> or <link rel="icon">
      try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 4500);
        const response = await fetch(formattedUrl, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          },
          signal: controller.signal,
        });
        clearTimeout(timeout);

        if (response.ok) {
          const html = await response.text();

          // Check for apple-touch-icon first (highest quality, 180x180 or 192x192)
          const appleMatch =
            html.match(/<link[^>]+rel=["'](?:apple-touch-icon|apple-touch-icon-precomposed)["'][^>]*href=["']([^"']+)["']/i) ||
            html.match(/<link[^>]+href=["']([^"']+)["'][^>]*rel=["'](?:apple-touch-icon|apple-touch-icon-precomposed)["']/i);

          if (appleMatch && appleMatch[1]) {
            let iconPath = appleMatch[1].trim();
            if (iconPath.startsWith('//')) iconPath = `https:${iconPath}`;
            else if (iconPath.startsWith('/')) iconPath = `${origin}${iconPath}`;
            else if (!iconPath.startsWith('http')) iconPath = `${origin}/${iconPath}`;
            candidateIcon = iconPath;
            source = 'apple-touch-icon';
          } else {
            // Check for standard icon or shortcut icon
            const iconMatch =
              html.match(/<link[^>]+rel=["'](?:icon|shortcut icon)["'][^>]*href=["']([^"']+)["']/i) ||
              html.match(/<link[^>]+href=["']([^"']+)["'][^>]*rel=["'](?:icon|shortcut icon)["']/i);

            if (iconMatch && iconMatch[1]) {
              let iconPath = iconMatch[1].trim();
              if (iconPath.startsWith('//')) iconPath = `https:${iconPath}`;
              else if (iconPath.startsWith('/')) iconPath = `${origin}${iconPath}`;
              else if (!iconPath.startsWith('http')) iconPath = `${origin}/${iconPath}`;
              candidateIcon = iconPath;
              source = 'html-link';
            }
          }
        }
      } catch (err) {
        // Fallback gracefully on timeout or network error
      }

      // 2. If no candidate found in HTML, fallback to high-resolution Google S2 favicon service
      if (!candidateIcon) {
        candidateIcon = `https://www.google.com/s2/favicons?domain=${hostname}&sz=128`;
        source = 'google-s2';
      }

      res.json({
        url: formattedUrl,
        iconUrl: candidateIcon,
        source,
        domain: hostname.replace(/^www\./, ''),
        origin,
      });
    } catch (err: any) {
      res.status(400).json({
        error: err.message || 'URL inválida',
        iconUrl: `https://www.google.com/s2/favicons?domain=example.com&sz=128`,
        source: 'fallback',
      });
    }
  });

  // Link Verification API
  app.post('/api/verify-link', async (req, res) => {
    const { url } = req.body;
    if (!url) {
      res.status(400).json({ error: 'URL requerida' });
      return;
    }

    let formattedUrl = url.trim();
    if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
      formattedUrl = `https://${formattedUrl}`;
    }

    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 6000);

      const response = await fetch(formattedUrl, {
        method: 'GET',
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        },
        signal: controller.signal,
      });
      clearTimeout(timeout);

      const active = response.status >= 200 && response.status < 400;
      res.json({
        url: formattedUrl,
        active,
        status: response.status,
        error: active ? null : `Error HTTP ${response.status}`,
      });
    } catch (err: any) {
      res.json({
        url: formattedUrl,
        active: false,
        status: 0,
        error: err.name === 'AbortError' ? 'Tiempo de espera agotado' : (err.message || 'Error de conexión'),
      });
    }
  });

  // Proxy PDF API to bypass X-Frame-Options and CORS for inline iframe viewing
  app.get('/api/proxy-pdf', async (req, res) => {
    const rawUrl = req.query.url as string;
    if (!rawUrl) {
      res.status(400).send('URL requerida');
      return;
    }

    let formattedUrl = rawUrl.trim();
    if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
      formattedUrl = `https://${formattedUrl}`;
    }

    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 15000);

      const response = await fetch(formattedUrl, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
          'Accept': 'application/pdf,application/octet-stream,*/*',
        },
        signal: controller.signal,
      });
      clearTimeout(timeout);

      if (!response.ok) {
        res.status(response.status).send(`Error al obtener archivo PDF: HTTP ${response.status}`);
        return;
      }

      const arrayBuffer = await response.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="document.pdf"');
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.removeHeader('X-Frame-Options');
      res.removeHeader('Content-Security-Policy');
      res.send(buffer);
    } catch (err: any) {
      res.status(500).send(`Error al cargar PDF: ${err.message || 'Error de conexión'}`);
    }
  });

  // Reader Mode Extraction API
  app.post('/api/reader-mode', async (req, res) => {
    const { url, title = '' } = req.body;
    if (!url) {
      res.status(400).json({ error: 'URL requerida' });
      return;
    }

    let formattedUrl = url.trim();
    if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
      formattedUrl = `https://${formattedUrl}`;
    }

    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000);
      const response = await fetch(formattedUrl, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        },
        signal: controller.signal,
      });
      clearTimeout(timeout);

      const htmlText = await response.text();

      // Extract Title
      let extractedTitle = title;
      const titleMatch = htmlText.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
      if (titleMatch && titleMatch[1]) {
        extractedTitle = titleMatch[1].replace(/\s+/g, ' ').trim();
      }

      // Clean HTML scripts/styles/nav
      const cleanedHtml = htmlText
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
        .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, '')
        .replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, '')
        .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, '');

      // Extract Images
      const imgMatches = Array.from(cleanedHtml.matchAll(/<img[^>]+src=["']([^"']+)["']/gi));
      const extractedImages: string[] = [];
      for (const match of imgMatches) {
        let imgSrc = match[1];
        if (imgSrc.startsWith('//')) imgSrc = `https:${imgSrc}`;
        else if (imgSrc.startsWith('/')) {
          try {
            const origin = new URL(formattedUrl).origin;
            imgSrc = `${origin}${imgSrc}`;
          } catch (_) {}
        }
        if (imgSrc.startsWith('http') && !imgSrc.includes('icon') && !imgSrc.includes('logo') && !extractedImages.includes(imgSrc)) {
          extractedImages.push(imgSrc);
        }
      }

      // Extract Paragraphs
      const pMatches = Array.from(cleanedHtml.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi));
      let paragraphs = pMatches
        .map((m) => m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim())
        .filter((p) => p.length > 40);

      if (paragraphs.length === 0) {
        paragraphs = [cleanedHtml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 1500)];
      }

      // Gemini AI enhancement if available
      const ai = getAIClient();
      if (ai) {
        try {
          const rawText = paragraphs.slice(0, 10).join('\n\n');
          const aiResponse = await ai.models.generateContent({
            model: 'gemini-3.6-flash',
            contents: `Formatea el siguiente texto extraído de una web en párrafos limpios, legibles y bien redactados en español para un modo lectura sin distracciones.
Título: "${extractedTitle}"
Texto:
${rawText.slice(0, 3500)}`,
          });
          if (aiResponse.text) {
            paragraphs = aiResponse.text.split('\n\n').filter((p) => p.trim().length > 0);
          }
        } catch (e) {
          console.warn('Gemini reader mode refinement skipped:', e);
        }
      }

      res.json({
        url: formattedUrl,
        title: extractedTitle || 'Artículo en Modo Lectura',
        paragraphs,
        images: extractedImages.slice(0, 6),
        readingTimeMinutes: Math.max(1, Math.ceil(paragraphs.join(' ').split(' ').length / 200)),
      });
    } catch (err: any) {
      res.json({
        url: formattedUrl,
        title: title || 'Modo Lectura',
        paragraphs: [
          `No se pudo extraer el contenido directamente desde la página (${err.message || 'Error de red'}).`,
          'Puedes abrir el visor iframe o abrir el sitio web original en una nueva pestaña.',
        ],
        images: [],
        readingTimeMinutes: 1,
      });
    }
  });

  // Vite Middleware in Dev vs Static Files in Production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (_req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server listening on http://0.0.0.0:${PORT}`);
  });
}

startServer();
